#!/usr/bin/env python3
"""Generate protocol bindings from vivid_display_v1.toml."""

from __future__ import annotations

import argparse
import re
import sys
import tomllib
from dataclasses import dataclass
from pathlib import Path
from typing import Any

SPEC = Path(__file__).with_name("vivid_display_v1.toml")
PROTO_DIR = Path(__file__).parent
REPO_ROOT = PROTO_DIR.parent.parent.parent

GENERATED_BANNER = (
    "/* generated by protocol_gen.py from vivid_display_v1.toml — do not edit */"
)
PY_GENERATED_BANNER = (
    "# generated by protocol_gen.py from vivid_display_v1.toml — do not edit"
)
JS_GENERATED_BANNER = (
    "// generated by protocol_gen.py from vivid_display_v1.toml — do not edit"
)

TYPE_SIZE = {
    "u16": 2,
    "u32": 4,
    "i32": 4,
    "u64": 8,
    "i64": 8,
    "f32": 4,
    "f64": 8,
}

MESSAGE_BYTES_KEYS = {
    "control-header": "CONTROL_HEADER_BYTES",
    "pointer-motion": "POINTER_MOTION_BODY_BYTES",
    "pointer-button": "POINTER_BUTTON_BODY_BYTES",
    "pointer-axis": "POINTER_AXIS_BODY_BYTES",
    "frame-ready": "FRAME_READY_BODY_BYTES",
    "unbind": "UNBIND_BODY_BYTES",
}

SIZE_T_CONSTANTS = frozenset({"CODEC_MAX_BODY_BYTES", "CODEC_MAX_FDS_PER_MESSAGE"})
INT_CONSTANTS = frozenset({"CODEC_FRAME_DONE", "CODEC_FRAME_NEED_IO"})
ENUM_ORDER = (
    "result",
    "error-code",
    "client-role",
    "request-opcode",
    "event-opcode",
    "control-opcode",
    "button-state",
    "axis-source",
)

ERROR_SEGMENT_COMMENTS = {
    (1, 99): "/* 1-99 handshake/connection, terminal (producer disconnects afterward) */",
    (100, 199): "/* 100-199 caps/negotiation, non-terminal */",
    (200, 299): "/* 200-299 output lifecycle, non-terminal */",
    (300, 399): "/* 300-399 control, non-terminal */",
}


@dataclass(frozen=True)
class LayoutField:
    name: str
    type: str
    offset: int
    size: int | None
    count_field: str | None = None
    max_count: int | None = None


@dataclass(frozen=True)
class MessageLayout:
    slug: str
    kind: str
    fields: tuple[LayoutField, ...]
    fixed_size: int | None
    bytes_key: str | None
    c_base: str
    js_base: str


def _slug_to_c_base(slug: str) -> str:
    return slug.replace("-", "_")


def _slug_to_js_base(slug: str) -> str:
    parts = slug.split("-")
    return "".join(part[:1].upper() + part[1:] for part in parts)


def parse_message_layouts(spec: dict[str, Any]) -> list[MessageLayout]:
    layouts: list[MessageLayout] = []
    for slug, message in spec.get("messages", {}).items():
        if message.get("encoding") != "binary":
            continue
        offset = 0
        fields: list[LayoutField] = []
        for raw in message["fields"]:
            field_type = raw["type"]
            if field_type.endswith("[]"):
                element_type = field_type[:-2]
                if element_type not in TYPE_SIZE:
                    raise ValueError(f"unsupported array element type {element_type}")
                fields.append(
                    LayoutField(
                        name=raw["name"],
                        type=field_type,
                        offset=offset,
                        size=None,
                        count_field=raw.get("count-field"),
                        max_count=raw.get("max"),
                    )
                )
                offset = None
                break
            size = TYPE_SIZE[field_type]
            fields.append(
                LayoutField(
                    name=raw["name"],
                    type=field_type,
                    offset=offset,
                    size=size,
                    max_count=raw.get("max"),
                )
            )
            offset += size
        layouts.append(
            MessageLayout(
                slug=slug,
                kind=message.get("kind", ""),
                fields=tuple(fields),
                fixed_size=offset,
                bytes_key=MESSAGE_BYTES_KEYS.get(slug),
                c_base=_slug_to_c_base(slug),
                js_base=_slug_to_js_base(slug),
            )
        )
    return layouts


def _bytes_define_name(layout: MessageLayout) -> str | None:
    if layout.bytes_key is None:
        return None
    return f"VIVID_DISPLAY_{layout.bytes_key}"


def _struct_format_field(field_type: str) -> str:
    return {
        "u16": "H",
        "u32": "I",
        "i32": "i",
        "u64": "Q",
        "i64": "q",
        "f32": "f",
        "f64": "d",
    }[field_type]


def _c_param_type(field_type: str) -> str:
    return {
        "u16": "uint16_t",
        "u32": "uint32_t",
        "i32": "int32_t",
        "u64": "uint64_t",
        "i64": "int64_t",
        "f32": "float",
        "f64": "double",
    }[field_type]


def _js_param_type(field_type: str) -> str:
    return "number"


def _emit_c_codec_helpers() -> list[str]:
    return [
        "static inline void vivid_display_codec_write_u16(uint8_t* out, uint16_t value)",
        "{",
        "    out[0] = (uint8_t)(value & 0xffu);",
        "    out[1] = (uint8_t)((value >> 8) & 0xffu);",
        "}",
        "",
        "static inline uint16_t vivid_display_codec_read_u16(const uint8_t* in)",
        "{",
        "    return (uint16_t)in[0] | ((uint16_t)in[1] << 8);",
        "}",
        "",
        "static inline void vivid_display_codec_write_u32(uint8_t* out, uint32_t value)",
        "{",
        "    out[0] = (uint8_t)(value & 0xffu);",
        "    out[1] = (uint8_t)((value >> 8) & 0xffu);",
        "    out[2] = (uint8_t)((value >> 16) & 0xffu);",
        "    out[3] = (uint8_t)((value >> 24) & 0xffu);",
        "}",
        "",
        "static inline uint32_t vivid_display_codec_read_u32(const uint8_t* in)",
        "{",
        "    return (uint32_t)in[0] | ((uint32_t)in[1] << 8) | ((uint32_t)in[2] << 16) |",
        "           ((uint32_t)in[3] << 24);",
        "}",
        "",
        "static inline void vivid_display_codec_write_u64(uint8_t* out, uint64_t value)",
        "{",
        "    vivid_display_codec_write_u32(out, (uint32_t)(value & 0xffffffffu));",
        "    vivid_display_codec_write_u32(out + 4, (uint32_t)(value >> 32));",
        "}",
        "",
        "static inline uint64_t vivid_display_codec_read_u64(const uint8_t* in)",
        "{",
        "    return (uint64_t)vivid_display_codec_read_u32(in) |",
        "           ((uint64_t)vivid_display_codec_read_u32(in + 4) << 32);",
        "}",
        "",
        "static inline void vivid_display_codec_write_f32(uint8_t* out, float value)",
        "{",
        "    uint32_t bits = 0;",
        "    memcpy(&bits, &value, sizeof(bits));",
        "    vivid_display_codec_write_u32(out, bits);",
        "}",
        "",
        "static inline float vivid_display_codec_read_f32(const uint8_t* in)",
        "{",
        "    float value = 0.f;",
        "    uint32_t bits = vivid_display_codec_read_u32(in);",
        "    memcpy(&value, &bits, sizeof(value));",
        "    return value;",
        "}",
        "",
        "static inline void vivid_display_codec_write_f64(uint8_t* out, double value)",
        "{",
        "    uint64_t bits = 0;",
        "    memcpy(&bits, &value, sizeof(bits));",
        "    vivid_display_codec_write_u64(out, bits);",
        "}",
        "",
        "static inline double vivid_display_codec_read_f64(const uint8_t* in)",
        "{",
        "    double value = 0.0;",
        "    uint64_t bits = vivid_display_codec_read_u64(in);",
        "    memcpy(&value, &bits, sizeof(value));",
        "    return value;",
        "}",
        "",
    ]


def _c_write_field(field: LayoutField, value_expr: str) -> str:
    if field.type == "u16":
        return f"vivid_display_codec_write_u16(out + {field.offset}, {value_expr});"
    if field.type == "u32":
        return f"vivid_display_codec_write_u32(out + {field.offset}, {value_expr});"
    if field.type == "u64":
        return f"vivid_display_codec_write_u64(out + {field.offset}, {value_expr});"
    if field.type == "f32":
        return f"vivid_display_codec_write_f32(out + {field.offset}, {value_expr});"
    if field.type == "f64":
        return f"vivid_display_codec_write_f64(out + {field.offset}, {value_expr});"
    raise ValueError(f"unsupported write type {field.type}")


def _c_read_field(field: LayoutField, dest_expr: str) -> str:
    if field.type == "u16":
        return f"*({dest_expr}) = vivid_display_codec_read_u16(data + {field.offset});"
    if field.type == "u32":
        return f"*({dest_expr}) = vivid_display_codec_read_u32(data + {field.offset});"
    if field.type == "u64":
        return f"*({dest_expr}) = vivid_display_codec_read_u64(data + {field.offset});"
    if field.type == "f32":
        return f"*({dest_expr}) = vivid_display_codec_read_f32(data + {field.offset});"
    if field.type == "f64":
        return f"*({dest_expr}) = vivid_display_codec_read_f64(data + {field.offset});"
    raise ValueError(f"unsupported read type {field.type}")


def _emit_c_message_codec(layout: MessageLayout) -> list[str]:
    lines: list[str] = []
    scalar_fields = [field for field in layout.fields if not field.type.endswith("[]")]
    array_field = next((field for field in layout.fields if field.type.endswith("[]")), None)

    if layout.fixed_size is not None:
        params = ", ".join(
            f"{_c_param_type(field.type)} {field.name}" for field in scalar_fields
        )
        lines.append(
            f"static inline void vivid_display_{layout.c_base}_body_write("
            f"uint8_t out[{_bytes_define_name(layout)}], {params})"
        )
        lines.append("{")
        for field in scalar_fields:
            lines.append(f"    {_c_write_field(field, field.name)}")
        lines.append("}")
        lines.append("")

        out_params = ", ".join(
            f"{_c_param_type(field.type)}* {field.name}" for field in scalar_fields
        )
        lines.append(
            f"static inline int vivid_display_{layout.c_base}_body_read("
            f"const uint8_t* data, size_t len, {out_params})"
        )
        lines.append("{")
        lines.append(f"    if (!data || len < {_bytes_define_name(layout)})")
        lines.append("        return -1;")
        for field in scalar_fields:
            lines.append(f"    {_c_read_field(field, field.name)}")
        lines.append("    return 0;")
        lines.append("}")
        lines.append("")
        return lines

    if array_field is None:
        raise ValueError(f"message {layout.slug} has no fixed size and no array tail")

    lines.extend(
        [
            "static inline size_t vivid_display_audio_samples_bin_body_bytes(uint32_t count)",
            "{",
            "    return 12u + (size_t)count * sizeof(float);",
            "}",
            "",
            "static inline int vivid_display_audio_samples_bin_body_write(",
            "    uint8_t* out,",
            "    size_t out_cap,",
            "    uint32_t count,",
            "    uint64_t time_usec,",
            "    const float* samples)",
            "{",
            "    if (!out || !samples || count == 0 || count > VIVID_DISPLAY_AUDIO_SAMPLES_BIN_MAX_COUNT)",
            "        return -1;",
            "    const size_t need = vivid_display_audio_samples_bin_body_bytes(count);",
            "    if (out_cap < need)",
            "        return -1;",
            "    vivid_display_codec_write_u32(out, count);",
            "    vivid_display_codec_write_u64(out + 4, time_usec);",
            "    for (uint32_t i = 0; i < count; i++)",
            "        vivid_display_codec_write_f32(out + 12 + (size_t)i * sizeof(float), samples[i]);",
            "    return (int)need;",
            "}",
            "",
            "static inline int vivid_display_audio_samples_bin_body_read(",
            "    const uint8_t* data,",
            "    size_t len,",
            "    uint32_t* count,",
            "    uint64_t* time_usec,",
            "    float* samples,",
            "    size_t samples_cap)",
            "{",
            "    if (!data || !count || !time_usec || !samples || len < 12)",
            "        return -1;",
            "    *count = vivid_display_codec_read_u32(data);",
            "    if (*count == 0 || *count > VIVID_DISPLAY_AUDIO_SAMPLES_BIN_MAX_COUNT)",
            "        return -1;",
            "    const size_t need = vivid_display_audio_samples_bin_body_bytes(*count);",
            "    if (len < need || samples_cap < *count)",
            "        return -1;",
            "    *time_usec = vivid_display_codec_read_u64(data + 4);",
            "    for (uint32_t i = 0; i < *count; i++)",
            "        samples[i] = vivid_display_codec_read_f32(data + 12 + (size_t)i * sizeof(float));",
            "    return (int)need;",
            "}",
            "",
        ]
    )
    return lines


def emit_c_codec_section(layouts: list[MessageLayout]) -> list[str]:
    lines = ["", "#include <string.h>", ""]
    lines.extend(_emit_c_codec_helpers())
    for layout in layouts:
        lines.extend(_emit_c_message_codec(layout))
    return lines


def _js_write_field(field: LayoutField, value_expr: str) -> str:
    mapping = {
        "u16": f"view.setUint16({field.offset}, {value_expr}, true);",
        "u32": f"view.setUint32({field.offset}, {value_expr}, true);",
        "u64": f"view.setBigUint64({field.offset}, BigInt({value_expr}), true);",
        "f32": f"view.setFloat32({field.offset}, {value_expr}, true);",
        "f64": f"view.setFloat64({field.offset}, {value_expr}, true);",
    }
    return mapping[field.type]


def _js_read_field(field: LayoutField) -> str:
    mapping = {
        "u16": f"view.getUint16({field.offset}, true)",
        "u32": f"view.getUint32({field.offset}, true)",
        "u64": f"Number(view.getBigUint64({field.offset}, true))",
        "f32": f"view.getFloat32({field.offset}, true)",
        "f64": f"view.getFloat64({field.offset}, true)",
    }
    key = re.sub(r"_([a-z])", lambda match: match.group(1).upper(), field.name)
    if field.name == "output_id":
        key = "outputId"
    elif field.name == "time_usec":
        key = "timeUsec"
    elif field.name == "buffer_index":
        key = "bufferIndex"
    elif field.name == "target_time_usec":
        key = "targetTimeUsec"
    elif field.name == "delta_x":
        key = "deltaX"
    elif field.name == "delta_y":
        key = "deltaY"
    return f"        {key}: {_js_read_field_expr(field)},"


def _js_read_field_expr(field: LayoutField) -> str:
    mapping = {
        "u16": f"view.getUint16({field.offset}, true)",
        "u32": f"view.getUint32({field.offset}, true)",
        "u64": f"Number(view.getBigUint64({field.offset}, true))",
        "f32": f"view.getFloat32({field.offset}, true)",
        "f64": f"view.getFloat64({field.offset}, true)",
    }
    return mapping[field.type]


def emit_js_codec(layouts: list[MessageLayout], defines: dict[str, int | str]) -> str:
    imports = sorted(
        name
        for layout in layouts
        if layout.bytes_key and (define := f"VIVID_DISPLAY_{layout.bytes_key}") in defines
        for name in [define]
    )
    if "VIVID_DISPLAY_AUDIO_SAMPLES_BIN_MAX_COUNT" in defines:
        imports.append("VIVID_DISPLAY_AUDIO_SAMPLES_BIN_MAX_COUNT")
    import_lines = "\n".join(f"    {name}," for name in imports)
    lines = [
        JS_GENERATED_BANNER,
        "",
        "import {",
        import_lines,
        "} from './protocol-constants.js';",
        "",
    ]

    for layout in layouts:
        scalar_fields = [field for field in layout.fields if not field.type.endswith("[]")]
        if layout.fixed_size is not None:
            define_name = f"VIVID_DISPLAY_{layout.bytes_key}"
            params = ", ".join(field.name for field in scalar_fields)
            lines.append(f"export function encode{layout.js_base}({params}) {{")
            lines.append(f"    const body = new Uint8Array({define_name});")
            lines.append("    const view = new DataView(body.buffer, body.byteOffset, body.byteLength);")
            for field in scalar_fields:
                lines.append(f"    {_js_write_field(field, field.name)}")
            lines.append("    return body;")
            lines.append("}")
            lines.append("")
            lines.append(f"export function decode{layout.js_base}(body) {{")
            lines.append(f"    if (body.length !== {define_name})")
            lines.append(
                f'        throw new Error(`invalid {layout.slug.upper()} body length ${{body.length}}`);'
            )
            lines.append("    const view = new DataView(body.buffer, body.byteOffset, body.byteLength);")
            lines.append("    return {")
            for field in scalar_fields:
                lines.append(_js_read_field(field))
            lines.append("    };")
            lines.append("}")
            lines.append("")
            continue

        lines.extend(
            [
                "export function encodeAudioSamplesBin(count, timeUsec, samples) {",
                "    const body = new Uint8Array(12 + count * 4);",
                "    const view = new DataView(body.buffer, body.byteOffset, body.byteLength);",
                "    view.setUint32(0, count, true);",
                "    view.setBigUint64(4, BigInt(timeUsec), true);",
                "    for (let index = 0; index < count; index++)",
                "        view.setFloat32(12 + index * 4, samples[index], true);",
                "    return body;",
                "}",
                "",
                "export function decodeAudioSamplesBin(body) {",
                "    const view = new DataView(body.buffer, body.byteOffset, body.byteLength);",
                "    const count = view.getUint32(0, true);",
                "    const timeUsec = Number(view.getBigUint64(4, true));",
                "    const samples = new Array(count);",
                "    for (let index = 0; index < count; index++)",
                "        samples[index] = view.getFloat32(12 + index * 4, true);",
                "    return { count, timeUsec, samples };",
                "}",
                "",
            ]
        )
    return "\n".join(lines)


def emit_py_codec(layouts: list[MessageLayout]) -> str:
    lines = [
        PY_GENERATED_BANNER,
        "",
        "import struct",
        "",
    ]
    for layout in layouts:
        scalar_fields = [field for field in layout.fields if not field.type.endswith("[]")]
        func_base = layout.c_base
        if layout.fixed_size is not None:
            fmt = "<" + "".join(_struct_format_field(field.type) for field in scalar_fields)
            arglist = ", ".join(field.name for field in scalar_fields)
            lines.append(f"{func_base.upper()}_STRUCT = \"{fmt}\"")
            lines.append("")
            lines.append(f"def pack_{func_base}({arglist}):")
            lines.append(f"    return struct.pack({func_base.upper()}_STRUCT, {arglist})")
            lines.append("")
            lines.append(f"def unpack_{func_base}(body):")
            lines.append(f"    return struct.unpack({func_base.upper()}_STRUCT, body)")
            lines.append("")
            continue
        lines.extend(
            [
                "def pack_audio_samples_bin(count, time_usec, samples):",
                "    return struct.pack('<IQ', count, time_usec) + struct.pack('<' + ('f' * count), *samples)",
                "",
                "def unpack_audio_samples_bin(body):",
                "    count, time_usec = struct.unpack_from('<IQ', body, 0)",
                "    samples = struct.unpack_from('<' + ('f' * count), body, 12)",
                "    return count, time_usec, samples",
                "",
            ]
        )
    return "\n".join(lines)


def _segment_for_code(code: int, segments: list[dict[str, Any]]) -> dict[str, Any] | None:
    for segment in segments:
        low, high = segment["range"]
        if low <= code <= high:
            return segment
    return None


def _error_entries(spec: dict[str, Any]) -> list[tuple[str, int, str, bool]]:
    segments = spec.get("errors", {}).get("segments", [])
    prefix = spec["enums"]["error-code"]["prefix"]
    entries: list[tuple[str, int, str, bool]] = []
    for member in spec["enums"]["error-code"]["members"]:
        if "name" not in member:
            continue
        code = member["value"]
        segment = _segment_for_code(code, segments)
        domain = segment["domain"] if segment else "unknown"
        terminal = bool(segment["terminal"]) if segment else False
        entries.append((member["name"], code, domain, terminal))
    entries.sort(key=lambda item: item[1])
    return entries


def _named_value_entries(section: dict[str, Any]) -> list[tuple[str, int]]:
    prefix = section.get("prefix", "")
    entries: list[tuple[str, int]] = []
    for member in section.get("members", []):
        if "name" not in member:
            continue
        if "alias-of" in member:
            continue
        entries.append((member["name"], member["value"]))
    entries.sort(key=lambda item: item[1])
    return entries


def _client_role_entries(spec: dict[str, Any]) -> list[tuple[str, int]]:
    section = spec["enums"]["client-role"]
    entries: list[tuple[str, int]] = []
    for member in section["members"]:
        if "alias-of" in member:
            continue
        if "name" in member:
            entries.append((member["name"], member["value"]))
    entries.sort(key=lambda item: item[1])
    return entries


def _message_min_versions(spec: dict[str, Any]) -> list[tuple[str, int, str]]:
    entries: dict[str, tuple[int, str]] = {}
    for slug, message in spec.get("messages", {}).items():
        since = message.get("since")
        if since is None:
            continue
        key = message.get("opcode", slug.upper().replace("-", "_"))
        entries[key] = (since, message.get("kind", "message"))

    req_enum = spec.get("enums", {}).get("request-opcode", {})
    prefix = req_enum.get("prefix", "VIVID_DISPLAY_REQ_")
    for member in req_enum.get("members", []):
        since = member.get("since")
        if since is None or "name" not in member:
            continue
        entries[member["name"]] = (since, "request-opcode")

    return sorted((key, since, kind) for key, (since, kind) in entries.items())


def emit_c_metadata(spec: dict[str, Any]) -> list[str]:
    lines = ["", "#include <stdbool.h>", ""]
    error_entries = _error_entries(spec)

    lines.append("static inline const char* vivid_display_error_name(int code)")
    lines.append("{")
    lines.append("    switch (code) {")
    for name, code, _domain, _terminal in error_entries:
        lines.append(f'    case VIVID_DISPLAY_ERR_{name}: return "{name}";')
    lines.append("    default: return NULL;")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    lines.append("static inline bool vivid_display_error_terminal(int code)")
    lines.append("{")
    lines.append("    switch (code) {")
    for name, code, _domain, terminal in error_entries:
        if terminal:
            lines.append(f"    case VIVID_DISPLAY_ERR_{name}: return true;")
    lines.append("    default: return false;")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    lines.append("static inline const char* vivid_display_error_domain(int code)")
    lines.append("{")
    lines.append("    switch (code) {")
    for name, code, domain, _terminal in error_entries:
        lines.append(f'    case VIVID_DISPLAY_ERR_{name}: return "{domain}";')
    lines.append('    default: return "unknown";')
    lines.append("    }")
    lines.append("}")
    lines.append("")

    bind_failed = spec["bind-failed-reasons"]
    prefix = bind_failed["prefix"]
    lines.append("static inline const char* vivid_display_bind_failed_reason_name(uint32_t reason)")
    lines.append("{")
    lines.append("    switch (reason) {")
    for name, value in _named_value_entries(bind_failed):
        lines.append(f'    case {prefix}{name}: return "{name}";')
    lines.append("    default: return NULL;")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    flag_group = spec["flags"]["window"]
    flag_prefix = flag_group["prefix"]
    lines.append("static inline const char* vivid_display_window_flag_name(uint32_t flag)")
    lines.append("{")
    lines.append("    switch (flag) {")
    for name, value in _named_value_entries(flag_group):
        lines.append(f'    case {flag_prefix}{name}: return "{name}";')
    lines.append("    default: return NULL;")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    role_prefix = spec["enums"]["client-role"]["prefix"]
    lines.append("static inline const char* vivid_display_client_role_name(uint32_t role)")
    lines.append("{")
    lines.append("    switch (role) {")
    for name, value in _client_role_entries(spec):
        lines.append(f'    case {role_prefix}{name}: return "{name}";')
    lines.append("    default: return NULL;")
    lines.append("    }")
    lines.append("}")
    lines.append("")

    min_versions = _message_min_versions(spec)
    req_enum = spec.get("enums", {}).get("request-opcode", {})
    req_with_since = [
        (member["name"], member["since"])
        for member in req_enum.get("members", [])
        if "name" in member and member.get("since") is not None
    ]
    if req_with_since:
        lines.append("static inline uint32_t vivid_display_request_min_version(uint16_t opcode)")
        lines.append("{")
        lines.append("    switch (opcode) {")
        for name, since in req_with_since:
            lines.append(f"    case VIVID_DISPLAY_REQ_{name}: return {since}u;")
        lines.append("    default: return VIVID_DISPLAY_PROTOCOL_MIN_SUPPORTED;")
        lines.append("    }")
        lines.append("}")
        lines.append("")

    return lines


def emit_js_meta(spec: dict[str, Any]) -> str:
    error_entries = _error_entries(spec)
    lines = [
        JS_GENERATED_BANNER,
        "",
        "import {",
    ]
    const_names = sorted(
        {
            f"VIVID_DISPLAY_ERR_{name}"
            for name, _code, _domain, _terminal in error_entries
        }
        | {
            f"{spec['bind-failed-reasons']['prefix']}{name}"
            for name, _value in _named_value_entries(spec["bind-failed-reasons"])
        }
        | {
            f"{spec['flags']['window']['prefix']}{name}"
            for name, _value in _named_value_entries(spec["flags"]["window"])
        }
        | {
            f"{spec['enums']['client-role']['prefix']}{name}"
            for name, _value in _client_role_entries(spec)
        }
    )
    lines.extend(f"    {name}," for name in const_names)
    lines.extend(
        [
            "} from './protocol-constants.js';",
            "",
            "export const ERROR_NAMES = {",
        ]
    )
    for name, code, _domain, _terminal in error_entries:
        lines.append(f'    [VIVID_DISPLAY_ERR_{name}]: "{name}",')
    lines.extend(["};", ""])

    lines.extend(
        [
            "export const ERROR_DOMAINS = {",
        ]
    )
    for name, code, domain, _terminal in error_entries:
        lines.append(f'    [VIVID_DISPLAY_ERR_{name}]: "{domain}",')
    lines.extend(["};", ""])

    lines.extend(
        [
            "export const ERROR_TERMINAL = {",
        ]
    )
    for name, code, _domain, terminal in error_entries:
        lines.append(f"    [VIVID_DISPLAY_ERR_{name}]: {'true' if terminal else 'false'},")
    lines.extend(["};", ""])

    bind_prefix = spec["bind-failed-reasons"]["prefix"]
    lines.extend(["export const BIND_FAILED_REASON_NAMES = {"])
    for name, value in _named_value_entries(spec["bind-failed-reasons"]):
        lines.append(f'    [{bind_prefix}{name}]: "{name}",')
    lines.extend(["};", ""])

    flag_prefix = spec["flags"]["window"]["prefix"]
    lines.extend(["export const WINDOW_FLAG_NAMES = {"])
    for name, value in _named_value_entries(spec["flags"]["window"]):
        lines.append(f'    [{flag_prefix}{name}]: "{name}",')
    lines.extend(["};", ""])

    role_prefix = spec["enums"]["client-role"]["prefix"]
    lines.extend(["export const CLIENT_ROLE_NAMES = {"])
    for name, value in _client_role_entries(spec):
        lines.append(f'    [{role_prefix}{name}]: "{name}",')
    lines.extend(["};", ""])

    min_versions = _message_min_versions(spec)
    lines.extend(["export const MESSAGE_MIN_VERSION = {"])
    for key, since, _kind in min_versions:
        lines.append(f'    {key}: {since},')
    lines.extend(["};", ""])

    lines.extend(
        [
            "export function errorName(code) {",
            "    return ERROR_NAMES[code] ?? `UNKNOWN(${code})`;",
            "}",
            "",
            "export function errorDomain(code) {",
            '    return ERROR_DOMAINS[code] ?? "unknown";',
            "}",
            "",
            "export function errorIsTerminal(code) {",
            "    return ERROR_TERMINAL[code] === true;",
            "}",
            "",
            "export function bindFailedReasonName(reason) {",
            "    return BIND_FAILED_REASON_NAMES[reason] ?? `UNKNOWN(${reason})`;",
            "}",
            "",
            "export function windowFlagName(flag) {",
            "    return WINDOW_FLAG_NAMES[flag] ?? `UNKNOWN(${flag})`;",
            "}",
            "",
            "export function clientRoleName(role) {",
            "    return CLIENT_ROLE_NAMES[role] ?? `UNKNOWN(${role})`;",
            "}",
            "",
        ]
    )
    return "\n".join(lines)


def emit_hpp_meta(spec: dict[str, Any]) -> str:
    error_entries = _error_entries(spec)
    lines = [
        GENERATED_BANNER,
        "",
        "#pragma once",
        "",
        '#include "vivid_protocol_constants.hpp"',
        "",
        "#include <string_view>",
        "",
        'namespace vivid::protocol {',
        "",
        "inline constexpr std::string_view error_name(int code) noexcept",
        "{",
        "    switch (code) {",
    ]
    for name, code, _domain, _terminal in error_entries:
        lines.append(f'    case VIVID_DISPLAY_ERR_{name}: return "{name}";')
    lines.append('    default: return "UNKNOWN";')
    lines.extend(["    }", "}", ""])

    lines.append("inline constexpr bool error_is_terminal(int code) noexcept")
    lines.append("{")
    lines.append("    switch (code) {")
    for name, code, _domain, terminal in error_entries:
        if terminal:
            lines.append(f"    case VIVID_DISPLAY_ERR_{name}: return true;")
    lines.extend(["    default: return false;", "    }", "}", ""])

    lines.append("inline constexpr std::string_view error_domain(int code) noexcept")
    lines.append("{")
    lines.append("    switch (code) {")
    for name, code, domain, _terminal in error_entries:
        lines.append(f'    case VIVID_DISPLAY_ERR_{name}: return "{domain}";')
    lines.extend(['    default: return "unknown";', "    }", "}", ""])

    bind_prefix = spec["bind-failed-reasons"]["prefix"]
    lines.append("inline constexpr std::string_view bind_failed_reason_name(std::uint32_t reason) noexcept")
    lines.append("{")
    lines.append("    switch (reason) {")
    for name, value in _named_value_entries(spec["bind-failed-reasons"]):
        lines.append(f'    case {bind_prefix}{name}: return "{name}";')
    lines.extend(['    default: return "UNKNOWN";', "    }", "}", ""])

    flag_prefix = spec["flags"]["window"]["prefix"]
    lines.append("inline constexpr std::string_view window_flag_name(std::uint32_t flag) noexcept")
    lines.append("{")
    lines.append("    switch (flag) {")
    for name, value in _named_value_entries(spec["flags"]["window"]):
        lines.append(f'    case {flag_prefix}{name}: return "{name}";')
    lines.extend(['    default: return "UNKNOWN";', "    }", "}", ""])

    role_prefix = spec["enums"]["client-role"]["prefix"]
    lines.append("inline constexpr std::string_view client_role_name(std::uint32_t role) noexcept")
    lines.append("{")
    lines.append("    switch (role) {")
    for name, value in _client_role_entries(spec):
        lines.append(f'    case {role_prefix}{name}: return "{name}";')
    lines.extend(['    default: return "UNKNOWN";', "    }", "}", ""])

    min_versions = _message_min_versions(spec)
    if min_versions:
        lines.append("inline constexpr std::uint32_t message_min_version(std::string_view key) noexcept")
        lines.append("{")
        for key, since, _kind in min_versions:
            lines.append(f'    if (key == "{key}") return {since}u;')
        lines.append("    return VIVID_DISPLAY_PROTOCOL_MIN_SUPPORTED;")
        lines.append("}")
        lines.append("")

    lines.extend(["}  // namespace vivid::protocol", ""])
    return "\n".join(lines)


