def _field_macro_suffix(field: str) -> str:
    return re.sub(r"(?<=[a-z0-9])(?=[A-Z])", "_", field).upper()


def _json_field_macro(message: str, field: str) -> str:
    message_token = message.upper().replace("-", "_")
    return f"VIVID_JSON_{message_token}_{_field_macro_suffix(field)}"


def parse_json_field_groups(spec: dict[str, Any]) -> dict[str, dict[str, str]]:
    raw = spec.get("json-fields", {})
    groups: dict[str, dict[str, str]] = {}
    for message, fields in raw.items():
        if not isinstance(fields, dict):
            continue
        groups[message.upper()] = {key: str(value) for key, value in fields.items()}
    return groups


def parse_config_key_members(spec: dict[str, Any]) -> list[dict[str, Any]]:
    return list(spec.get("config-keys", {}).get("members", []))


CONFIG_SCHEMA_TYPE_C = {
    "bool": "VIVID_CONFIG_SCHEMA_BOOL",
    "int": "VIVID_CONFIG_SCHEMA_INT",
    "string": "VIVID_CONFIG_SCHEMA_STRING",
    "array": "VIVID_CONFIG_SCHEMA_ARRAY",
    "object": "VIVID_CONFIG_SCHEMA_OBJECT",
}


def emit_c_json_fields(groups: dict[str, dict[str, str]]) -> str:
    lines = [
        GENERATED_BANNER,
        "",
        "#ifndef VIVID_DISPLAY_PROTOCOL_JSON_H",
        "#define VIVID_DISPLAY_PROTOCOL_JSON_H",
        "",
    ]
    for message in sorted(groups):
        for field in sorted(groups[message]):
            wire = groups[message][field]
            lines.append(f'#define {_json_field_macro(message, field)} "{wire}"')
    lines.extend(["", "#endif", ""])
    return "\n".join(lines)


def emit_js_json_fields(groups: dict[str, dict[str, str]]) -> str:
    banner = GENERATED_BANNER.replace("/* ", "// ").replace(" */", "")
    lines = [banner, "", "export const J = {"]
    for index, message in enumerate(sorted(groups)):
        if index:
            lines.append("")
        lines.append(f"    {message}: {{")
        for field in sorted(groups[message]):
            wire = groups[message][field]
            lines.append(f'        {field}: "{wire}",')
        lines.append("    },")
    lines.extend(["};", ""])
    return "\n".join(lines)


def emit_hpp_json_fields(groups: dict[str, dict[str, str]]) -> str:
    lines = [
        GENERATED_BANNER,
        "",
        "#pragma once",
        "",
        "#include <QString>",
        "",
        "namespace vivid::protocol {",
        "",
    ]
    for message in sorted(groups):
        lines.append(f"struct {message} {{")
        for field in sorted(groups[message]):
            wire = groups[message][field]
            lines.append(f'    static inline const QString {field}{{QStringLiteral("{wire}")}};')
        lines.append("};")
        lines.append("")
    lines.extend(["}  // namespace vivid::protocol", ""])
    return "\n".join(lines)


def emit_py_json_fields(groups: dict[str, dict[str, str]]) -> str:
    lines = [PY_GENERATED_BANNER, "", "J = {"]
    for message in sorted(groups):
        lines.append(f'    "{message}": {{')
        for field in sorted(groups[message]):
            wire = groups[message][field]
            lines.append(f'        "{field}": "{wire}",')
        lines.append("    },")
    lines.extend(["}", ""])
    return "\n".join(lines)


def emit_c_config_schema(members: list[dict[str, Any]]) -> str:
    lines = [
        GENERATED_BANNER,
        "",
        "#ifndef VIVID_PRODUCER_CONFIG_SCHEMA_H",
        "#define VIVID_PRODUCER_CONFIG_SCHEMA_H",
        "",
        "#include <glib.h>",
        "",
        "typedef enum",
        "{",
        "    VIVID_CONFIG_SCHEMA_BOOL,",
        "    VIVID_CONFIG_SCHEMA_INT,",
        "    VIVID_CONFIG_SCHEMA_STRING,",
        "    VIVID_CONFIG_SCHEMA_ARRAY,",
        "    VIVID_CONFIG_SCHEMA_OBJECT,",
        "} VividConfigSchemaType;",
        "",
        "typedef struct",
        "{",
        "    const gchar* kebab_key;",
        "    const gchar* camel_key;",
        "    VividConfigSchemaType type;",
        "} VividConfigSchemaEntry;",
        "",
        "static const VividConfigSchemaEntry vivid_set_state_schema[] = {",
    ]
    for member in members:
        schema_type = member["type"]
        if schema_type not in CONFIG_SCHEMA_TYPE_C:
            raise ValueError(f"unsupported config key type: {schema_type}")
        camel = member.get("camel")
        camel_text = f"\"{camel}\"" if camel else "NULL"
        lines.append(
            f'    {{"{member["kebab"]}", {camel_text}, {CONFIG_SCHEMA_TYPE_C[schema_type]}}},'
        )
    lines.extend(
        [
            "};",
            "",
            "#endif",
            "",
        ]
    )
    return "\n".join(lines)


def emit_py_config_keys(members: list[dict[str, Any]]) -> str:
    lines = [PY_GENERATED_BANNER, ""]
    for member in members:
        token = member["kebab"].upper().replace("-", "_")
        lines.append(f'{token} = "{member["kebab"]}"')
        camel = member.get("camel")
        if camel:
            lines.append(f"{token}_CAMEL = \"{camel}\"")
        lines.append("")
    return "\n".join(lines)


