def _wire_type_name(field_type: str) -> str:
    if field_type.endswith("[]"):
        element = field_type[:-2]
        return f"{_wire_type_name(element)}[]"
    return f"{field_type}le"


def _layouts_by_opcode(spec: dict[str, Any]) -> dict[str, str]:
    mapping: dict[str, str] = {}
    for slug, message in spec.get("messages", {}).items():
        opcode = message.get("opcode")
        if opcode:
            mapping[opcode] = slug
    return mapping


def _request_body_summary(
    name: str,
    layouts_by_opcode: dict[str, str],
    layouts: list[MessageLayout],
    json_groups: dict[str, dict[str, str]],
) -> str:
    if name in layouts_by_opcode:
        slug = layouts_by_opcode[name]
        layout = next(item for item in layouts if item.slug == slug)
        if layout.fixed_size is None:
            return f"binary, variable ({slug})"
        return f"binary, {layout.fixed_size} bytes"
    if name == "CONTROL":
        return "control header + JSON"
    if name in REQUEST_JSON_GROUPS:
        return "JSON"
    if name == "BYE":
        return "empty/ignored"
    if name in ("MEDIA_STATE", "AUDIO_SAMPLES"):
        return "JSON"
    return "JSON"


def _event_body_summary(
    name: str,
    layouts_by_opcode: dict[str, str],
    layouts: list[MessageLayout],
) -> str:
    if name in layouts_by_opcode:
        slug = layouts_by_opcode[name]
        layout = next(item for item in layouts if item.slug == slug)
        if layout.fixed_size is None:
            return f"binary, variable ({slug})"
        return f"binary, {layout.fixed_size} bytes"
    if name == "CONTROL":
        return "control header + JSON"
    if name in EVENT_JSON_GROUPS:
        return "JSON"
    if name == "AUDIO_FRAME":
        return "unused currently"
    return "JSON"


def _emit_md_table(headers: list[str], rows: list[list[str]]) -> list[str]:
    lines = [
        "| " + " | ".join(headers) + " |",
        "| " + " | ".join("---" for _ in headers) + " |",
    ]
    for row in rows:
        lines.append("| " + " | ".join(row) + " |")
    return lines


def _emit_binary_layout_section(layout: MessageLayout, spec_messages: dict[str, Any]) -> list[str]:
    slug = layout.slug
    message = spec_messages[slug]
    title = slug.replace("-", " ").title()
    lines = [f"### `{slug}`", ""]
    opcode = message.get("opcode")
    if opcode:
        lines.append(f"- Opcode constant: `{opcode}`")
    since = message.get("since")
    if since is not None:
        lines.append(f"- Since protocol version: `{since}`")
    lines.append("")

    if layout.fixed_size is None:
        lines.append("Variable-length binary body.")
        lines.append("")
        for field in layout.fields:
            if field.type.endswith("[]"):
                lines.append(
                    f"- `{field.name}`: `{_wire_type_name(field.type)}`, "
                    f"count from `{field.count_field}` (max {field.max_count})"
                )
            else:
                lines.append(
                    f"- `{field.name}` @ offset {field.offset}: "
                    f"`{_wire_type_name(field.type)}`"
                )
        lines.append("")
        return lines

    rows: list[list[str]] = []
    for field in layout.fields:
        rows.append(
            [
                str(field.offset),
                str(field.size),
                f"`{_wire_type_name(field.type)}`",
                f"`{field.name}`",
            ]
        )
    lines.extend(_emit_md_table(["Offset", "Size", "Type", "Field"], rows))
    lines.append("")
    return lines


def emit_docs_reference(
    spec: dict[str, Any],
    layouts: list[MessageLayout],
    json_groups: dict[str, dict[str, str]],
    config_members: list[dict[str, Any]],
) -> str:
    protocol = spec["protocol"]
    constants = spec.get("constants", {})
    layouts_by_opcode = _layouts_by_opcode(spec)
    spec_messages = spec.get("messages", {})
    lines = [
        DOCS_BANNER,
        "",
        "# Vivid Display Protocol Reference",
        "",
        "Machine-readable tables generated from "
        "`producer/src/protocol/vivid_display_v1.toml`. "
        "Semantic prose, state machines, and invariants: `docs/protocols.md`.",
        "",
        "## Protocol identity",
        "",
        f"- Name: `{protocol['name']}`",
        f"- Current version: `{protocol['version']}`",
        f"- Minimum supported HELLO version: `{protocol['min-supported']}`",
        "",
    ]

    history = spec.get("history", [])
    if history:
        lines.extend(["## Version history", ""])
        rows = [[str(entry["version"]), entry["summary"]] for entry in history]
        lines.extend(_emit_md_table(["Version", "Summary"], rows))
        lines.append("")

    lines.extend(["## Transport constants", ""])
    transport_rows = [
        ["`CODEC_MAX_BODY_BYTES`", str(constants["CODEC_MAX_BODY_BYTES"])],
        ["`CODEC_MAX_FDS_PER_MESSAGE`", str(constants["CODEC_MAX_FDS_PER_MESSAGE"])],
        ["`FRAME_HEADER_BYTES`", str(constants["FRAME_HEADER_BYTES"])],
        ["`FRAME_READY_FD_COUNT`", str(constants["FRAME_READY_FD_COUNT"])],
        ["`DMABUF_MAX_PLANES`", str(constants["DMABUF_MAX_PLANES"])],
        ["`AUDIO_SAMPLES_BIN_MAX_COUNT`", str(constants["AUDIO_SAMPLES_BIN_MAX_COUNT"])],
    ]
    lines.extend(_emit_md_table(["Constant", "Value"], transport_rows))
    lines.append("")

    lines.extend(
        [
            "## Display transport frame header",
            "",
            "Every display socket message:",
            "",
        ]
    )
    lines.extend(
        _emit_md_table(
            ["Offset", "Size", "Type", "Field"],
            [
                ["0", "2", "`u16le`", "`opcode`"],
                ["2", "2", "`u16le`", "`total_length` (includes 4-byte header)"],
                ["4", "`total_length - 4`", "bytes", "`body`"],
            ],
        )
    )
    lines.append("")

    request_enum = spec["enums"]["request-opcode"]
    req_prefix = request_enum["prefix"]
    req_rows: list[list[str]] = []
    for member in request_enum["members"]:
        if "reserved" in member:
            req_rows.append(
                [
                    str(member["reserved"]),
                    "*(reserved)*",
                    "—",
                    "0",
                    member.get("reason", ""),
                ]
            )
            continue
        name = member["name"]
        since = member.get("since")
        notes = member.get("doc", "").strip().replace("\n", " ")
        if since is not None:
            notes = f"since v{since}. {notes}".strip()
        req_rows.append(
            [
                str(member["value"]),
                f"`{req_prefix}{name}`",
                _request_body_summary(name, layouts_by_opcode, layouts, json_groups),
                REQUEST_FD_COUNTS.get(name, "0"),
                notes,
            ]
        )
    lines.extend(["## Request opcodes (client -> producer)", ""])
    lines.extend(
        _emit_md_table(["Opcode", "Name", "Body", "FDs", "Notes"], req_rows)
    )
    lines.append("")

    event_enum = spec["enums"]["event-opcode"]
    evt_prefix = event_enum["prefix"]
    evt_rows: list[list[str]] = []
    for member in event_enum["members"]:
        if "reserved" in member:
            evt_rows.append(
                [
                    str(member["reserved"]),
                    "*(reserved)*",
                    "—",
                    "0",
                    member.get("reason", ""),
                ]
            )
            continue
        name = member["name"]
        notes = member.get("doc", "").strip().replace("\n", " ")
        since = member.get("since")
        if since is not None:
            notes = f"since v{since}. {notes}".strip()
        evt_rows.append(
            [
                str(member["value"]),
                f"`{evt_prefix}{name}`",
                _event_body_summary(name, layouts_by_opcode, layouts),
                EVENT_FD_COUNTS.get(name, "0"),
                notes,
            ]
        )
    lines.extend(["## Event opcodes (producer -> client)", ""])
    lines.extend(_emit_md_table(["Opcode", "Name", "Body", "FDs", "Notes"], evt_rows))
    lines.append("")

    control_enum = spec["enums"]["control-opcode"]
    ctl_prefix = control_enum["prefix"]
    ctl_rows: list[list[str]] = []
    for member in control_enum["members"]:
        if "reserved" in member:
            ctl_rows.append(
                [
                    str(member["reserved"]),
                    "*(reserved)*",
                    "—",
                    "—",
                    member.get("reason", ""),
                ]
            )
            continue
        name = member["name"]
        direction = CONTROL_DIRECTION.get(name, "producer -> controller")
        ctl_rows.append(
            [
                str(member["value"]),
                f"`{ctl_prefix}{name}`",
                direction,
                member.get("doc", "").strip(),
            ]
        )
    lines.extend(["## Control opcodes", ""])
    lines.extend(_emit_md_table(["Opcode", "Name", "Direction", "Notes"], ctl_rows))
    lines.append("")

    error_enum = spec["enums"]["error-code"]
    err_prefix = error_enum["prefix"]
    err_rows: list[list[str]] = []
    for member in error_enum["members"]:
        if "reserved" in member or "alias-of" in member:
            continue
        err_rows.append(
            [str(member["value"]), f"`{err_prefix}{member['name']}`", ""]
        )
    lines.extend(["## Error codes (`EVT_ERROR` JSON `code`)", ""])
    lines.extend(_emit_md_table(["Code", "Name", "Notes"], err_rows))
    lines.append("")

    segments = spec.get("errors", {}).get("segments", [])
    if segments:
        seg_rows = [
            [
                f"{segment['range'][0]}..{segment['range'][1]}",
                segment["domain"],
                "yes" if segment.get("terminal") else "no",
            ]
            for segment in segments
        ]
        lines.extend(["## Error code segments", ""])
        lines.extend(
            _emit_md_table(["Range", "Domain", "Terminal (disconnect)"], seg_rows)
        )
        lines.append("")

    bind_failed = spec.get("bind-failed-reasons", {})
    if bind_failed.get("members"):
        prefix = bind_failed.get("prefix", "")
        bf_rows = [
            [str(member["value"]), f"`{prefix}{member['name']}`", member.get("doc", "")]
            for member in bind_failed["members"]
        ]
        lines.extend(["## BIND_FAILED reason codes", ""])
        lines.extend(_emit_md_table(["Value", "Name", "Notes"], bf_rows))
        lines.append("")

    for flag_name, flag_group in spec.get("flags", {}).items():
        prefix = flag_group["prefix"]
        doc = flag_group.get("doc", "")
        flag_rows = [
            [
                str(member["value"]),
                f"`{prefix}{member['name']}`",
                member.get("doc", ""),
            ]
            for member in flag_group["members"]
        ]
        lines.extend([f"## Window flags (`{flag_name}`)", ""])
        if doc:
            lines.append(doc)
            lines.append("")
        lines.extend(_emit_md_table(["Bit", "Name", "Notes"], flag_rows))
        lines.append("")

    role_enum = spec["enums"]["client-role"]
    role_prefix = role_enum["prefix"]
    role_values: dict[str, int] = {}
    for member in role_enum["members"]:
        if "name" in member and "value" in member:
            role_values[member["name"]] = member["value"]
    role_rows: list[list[str]] = []
    for member in role_enum["members"]:
        if "reserved" in member:
            continue
        alias = member.get("alias-of")
        if alias:
            value = role_values[alias]
            role_rows.append(
                [
                    str(value),
                    f"`{role_prefix}{member['name']}`",
                    f"alias of `{role_prefix}{alias}`",
                ]
            )
            continue
        role_rows.append(
            [
                str(member["value"]),
                f"`{role_prefix}{member['name']}`",
                member.get("doc", ""),
            ]
        )
    lines.extend(["## Client roles (HELLO `role`)", ""])
    lines.extend(_emit_md_table(["Value", "Name", "Notes"], role_rows))
    lines.append("")

    for enum_key in ("button-state", "axis-source", "result"):
        enum_spec = spec["enums"][enum_key]
        prefix = enum_spec["prefix"]
        title = enum_key.replace("-", " ").title()
        enum_rows = [
            [str(member["value"]), f"`{prefix}{member['name']}`", member.get("doc", "")]
            for member in enum_spec["members"]
            if "reserved" not in member and "alias-of" not in member
        ]
        lines.extend([f"## {title}", ""])
        lines.extend(_emit_md_table(["Value", "Name", "Notes"], enum_rows))
        lines.append("")

    lines.extend(["## Binary message layouts", ""])
    for layout in layouts:
        lines.extend(_emit_binary_layout_section(layout, spec_messages))

    lines.extend(["## JSON wire field names", ""])
    for group in sorted(json_groups):
        rows = [
            [f"`{field}`", f"`{wire}`"]
            for field, wire in sorted(json_groups[group].items())
        ]
        lines.extend([f"### `{group}`", ""])
        lines.extend(_emit_md_table(["Logical id", "Wire name"], rows))
        lines.append("")

    if config_members:
        schema_rows: list[list[str]] = []
        for member in config_members:
            aliases = member.get("camel", "")
            schema_rows.append(
                [
                    f"`{member['kebab']}`",
                    f"`{aliases}`" if aliases else "",
                    member["type"],
                ]
            )
        lines.extend(["## CONTROL_SET_STATE schema keys", ""])
        lines.extend(
            _emit_md_table(["Canonical key", "Accepted alias", "Type"], schema_rows)
        )
        lines.append("")

    return "\n".join(lines)


def load_spec(path: Path) -> dict[str, Any]:
    with path.open("rb") as handle:
        return tomllib.load(handle)


def _constant_value(raw: int | str | dict[str, Any]) -> int | str:
    if isinstance(raw, dict):
        return raw["value"]
    return raw


def _resolve_enum_members(
    members: list[dict[str, Any]], prefix: str
) -> dict[str, int | str]:
    named: dict[str, int] = {}
    aliases: list[tuple[str, str]] = []
    seen_values: set[int] = set()

    for member in members:
        if "reserved" in member:
            slot = member["reserved"]
            if slot in seen_values:
                raise ValueError(f"reserved slot {slot} conflicts with existing value")
            seen_values.add(slot)
            continue
        if "alias-of" in member:
            aliases.append((member["name"], member["alias-of"]))
            continue
        name = member["name"]
        value = member["value"]
        if value in seen_values:
            raise ValueError(f"duplicate enum value {value} for {prefix}{name}")
        seen_values.add(value)
        named[name] = value

    out: dict[str, int | str] = {f"{prefix}{name}": value for name, value in named.items()}
    for alias_name, target_name in aliases:
        if target_name not in named:
            raise ValueError(f"alias {alias_name} references unknown member {target_name}")
        out[f"{prefix}{alias_name}"] = named[target_name]
    return out


def validate_spec(spec: dict[str, Any], layouts: list[MessageLayout]) -> None:
    protocol = spec["protocol"]
    max_version = protocol["version"]

    for section in spec.get("enums", {}).values():
        for member in section.get("members", []):
            since = member.get("since")
            if since is not None and since > max_version:
                raise ValueError(
                    f"since={since} exceeds protocol.version={max_version} "
                    f"for {section.get('prefix', '')}{member.get('name', '')}"
                )

    error_members = spec.get("enums", {}).get("error-code", {}).get("members", [])
    segments = spec.get("errors", {}).get("segments", [])
    for member in error_members:
        if "reserved" in member or "alias-of" in member:
            continue
        code = member["value"]
        matched = any(
            segment["range"][0] <= code <= segment["range"][1] for segment in segments
        )
        if not matched:
            raise ValueError(
                f"error code {code} ({member['name']}) falls outside declared segments"
            )

    for layout in layouts:
        if layout.fixed_size is None:
            continue
        if layout.bytes_key is None:
            raise ValueError(f"fixed-size message {layout.slug} missing bytes constant mapping")


def build_defines(spec: dict[str, Any], layouts: list[MessageLayout]) -> dict[str, int | str]:
    protocol = spec["protocol"]
    defines: dict[str, int | str] = {
        "VIVID_DISPLAY_PROTOCOL_NAME": protocol["name"],
        "VIVID_DISPLAY_PROTOCOL_VERSION": protocol["version"],
        "VIVID_DISPLAY_PROTOCOL_MIN_SUPPORTED": protocol["min-supported"],
    }

    for key, raw in spec.get("constants", {}).items():
        defines[f"VIVID_DISPLAY_{key}"] = _constant_value(raw)

    bind_failed = spec.get("bind-failed-reasons", {})
    prefix = bind_failed.get("prefix", "")
    for member in bind_failed.get("members", []):
        defines[f"{prefix}{member['name']}"] = member["value"]

    for flag_group in spec.get("flags", {}).values():
        flag_prefix = flag_group["prefix"]
        for member in flag_group["members"]:
            defines[f"{flag_prefix}{member['name']}"] = member["value"]

    for enum_spec in spec.get("enums", {}).values():
        defines.update(_resolve_enum_members(enum_spec["members"], enum_spec["prefix"]))

    for layout in layouts:
        if layout.bytes_key and layout.fixed_size is not None:
            defines[f"VIVID_DISPLAY_{layout.bytes_key}"] = layout.fixed_size

    return defines


def _format_c_scalar_define(name: str, key: str, value: int | str) -> str:
    if isinstance(value, str):
        return f'#define {name} "{value}"'
    if key in SIZE_T_CONSTANTS:
        return f"#define {name} ((size_t){value}u)"
    if key in INT_CONSTANTS:
        return f"#define {name} {value}"
    return f"#define {name} {value}u"


def _emit_c_enum(enum_spec: dict[str, Any], *, segment_comments: bool = False) -> list[str]:
    prefix = enum_spec["prefix"]
    c_name = enum_spec["c-name"]
    lines = ["typedef enum", "{"]
    emitted_segments: set[tuple[int, int]] = set()

    for member in enum_spec["members"]:
        if "reserved" in member:
            continue

        if "alias-of" in member:
            target = f"{prefix}{member['alias-of']}"
            lines.append(f"    {prefix}{member['name']} = {target},")
            continue

        value = member["value"]
        if segment_comments:
            for bounds, comment in ERROR_SEGMENT_COMMENTS.items():
                if bounds[0] <= value <= bounds[1] and bounds not in emitted_segments:
                    lines.append(f"    {comment}")
                    emitted_segments.add(bounds)
                    break

        doc = member.get("doc", "")
        if doc and "\n" in doc:
            lines.append("    /*")
            for line in doc.strip().splitlines():
                if line.strip():
                    lines.append(f"     * {line.rstrip()}")
                else:
                    lines.append("     *")
            lines.append("     */")

        suffix = ""
        if doc and "\n" not in doc:
            suffix = f" /* {doc} */"

        lines.append(f"    {prefix}{member['name']} = {value},{suffix}")

    lines.append(f"}} {c_name};")
    return lines


def emit_c_ids(spec: dict[str, Any], layouts: list[MessageLayout]) -> str:
    protocol = spec["protocol"]
    lines = [
        GENERATED_BANNER,
        "",
        "#ifndef VIVID_DISPLAY_PROTOCOL_IDS_H",
        "#define VIVID_DISPLAY_PROTOCOL_IDS_H",
        "",
        "#include <stddef.h>",
        "#include <stdint.h>",
        "",
        f'#define VIVID_DISPLAY_PROTOCOL_NAME "{protocol["name"]}"',
        f'#define VIVID_DISPLAY_PROTOCOL_VERSION {protocol["version"]}u',
        f"#define VIVID_DISPLAY_PROTOCOL_MIN_SUPPORTED {protocol['min-supported']}u",
        "",
        "/*",
        " * Protocol version history (negotiatedVersion = min(client, producer)):",
    ]
    for entry in spec.get("history", []):
        summary = entry["summary"].strip()
        lines.append(f" * v{entry['version']}  {summary}")
    lines.extend([" */", ""])

    window_schema = _constant_value(spec["constants"]["WINDOW_STATE_SCHEMA_V2"])
    lines.append(f'#define VIVID_DISPLAY_WINDOW_STATE_SCHEMA_V2 "{window_schema}"')
    lines.append("")

    flag_group = spec["flags"]["window"]
    lines.append(f"/* {flag_group['doc'].split(';')[0]} */")
    for member in flag_group["members"]:
        name = f"{flag_group['prefix']}{member['name']}"
        doc = member.get("doc", "")
        suffix = f" /* {doc} */" if doc else ""
        lines.append(f"#define {name} {member['value']}u{suffix}")
    lines.append("/* bits 4..31 reserved: senders must zero them; receivers must ignore them */")
    lines.append("")

    bind_failed = spec["bind-failed-reasons"]
    bind_prefix = bind_failed["prefix"]
    bind_width = max(len(f"{bind_prefix}{member['name']}") for member in bind_failed["members"])
    for member in bind_failed["members"]:
        name = f"{bind_prefix}{member['name']}"
        lines.append(f"#define {name.ljust(bind_width)} {member['value']}u")
    lines.append("")

    for key, raw in spec["constants"].items():
        if key == "WINDOW_STATE_SCHEMA_V2":
            continue
        name = f"VIVID_DISPLAY_{key}"
        value = _constant_value(raw)
        lines.append(_format_c_scalar_define(name, key, value))

    for layout in layouts:
        if layout.bytes_key and layout.fixed_size is not None:
            key = layout.bytes_key
            name = f"VIVID_DISPLAY_{key}"
            lines.append(_format_c_scalar_define(name, key, layout.fixed_size))
    lines.append("")

    enums = spec.get("enums", {})
    for index, enum_key in enumerate(ENUM_ORDER):
        if index:
            lines.append("")
        enum_spec = enums[enum_key]
        lines.extend(
            _emit_c_enum(
                enum_spec,
                segment_comments=(enum_key == "error-code"),
            )
        )

    lines.extend(emit_c_codec_section(layouts))
    lines.extend(emit_c_metadata(spec))
    lines.extend(["", "#endif", ""])
    return "\n".join(lines)


def collect_c_macro_names(spec: dict[str, Any], layouts: list[MessageLayout]) -> list[str]:
    names = [
        "VIVID_DISPLAY_PROTOCOL_NAME",
        "VIVID_DISPLAY_PROTOCOL_VERSION",
        "VIVID_DISPLAY_PROTOCOL_MIN_SUPPORTED",
        "VIVID_DISPLAY_WINDOW_STATE_SCHEMA_V2",
    ]

    flag_group = spec["flags"]["window"]
    for member in flag_group["members"]:
        names.append(f"{flag_group['prefix']}{member['name']}")

    bind_prefix = spec["bind-failed-reasons"]["prefix"]
    for member in spec["bind-failed-reasons"]["members"]:
        names.append(f"{bind_prefix}{member['name']}")

    for key in spec["constants"]:
        if key == "WINDOW_STATE_SCHEMA_V2":
            continue
        names.append(f"VIVID_DISPLAY_{key}")

    for layout in layouts:
        if layout.bytes_key and layout.fixed_size is not None:
            names.append(f"VIVID_DISPLAY_{layout.bytes_key}")

    return sorted(set(names))


def emit_kde_cpp(spec: dict[str, Any], layouts: list[MessageLayout]) -> str:
    lines = [
        GENERATED_BANNER,
        "",
        "#pragma once",
        "",
        '#include "vivid_protocol_constants.hpp"',
        "",
        "extern \"C\" {",
        '#include "vivid_display_protocol.h"',
        "}",
        "",
    ]
    for name in collect_c_macro_names(spec, layouts):
        lines.append(f"#undef {name}")
    lines.append("")
    return "\n".join(lines)


def emit_js(defines: dict[str, int | str]) -> str:
    lines = [GENERATED_BANNER, ""]
    for name in sorted(defines):
        value = defines[name]
        if isinstance(value, str):
            lines.append(f'export const {name} = "{value}";')
        else:
            lines.append(f"export const {name} = {value};")
    return "\n".join(lines) + "\n"


def emit_hpp(defines: dict[str, int | str]) -> str:
    lines = [
        GENERATED_BANNER,
        "",
        "#pragma once",
        "",
        "#include <cstdint>",
        "",
        "namespace vivid::protocol {",
        "",
    ]
    for name in sorted(defines):
        value = defines[name]
        if isinstance(value, str):
            lines.append(f'inline constexpr char {name}[] = "{value}";')
        else:
            lines.append(f"inline constexpr std::uint32_t {name} = {value}u;")
    lines.extend(["", "}  // namespace vivid::protocol", ""])
    return "\n".join(lines)


def emit_py(defines: dict[str, int | str]) -> str:
    lines = [PY_GENERATED_BANNER, ""]
    for name in sorted(defines):
        value = defines[name]
        if isinstance(value, str):
            lines.append(f'{name} = "{value}"')
        else:
            lines.append(f"{name} = {value}")
    return "\n".join(lines) + "\n"


def write_if_changed(path: Path, content: str) -> bool:
    if path.exists() and path.read_text(encoding="utf-8") == content:
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return True


def sync_bytes(canonical: Path, mirror: Path) -> bool:
    data = canonical.read_bytes()
    if mirror.exists() and mirror.read_bytes() == data:
        return False
    mirror.parent.mkdir(parents=True, exist_ok=True)
    mirror.write_bytes(data)
    return True


def check_bytes(canonical: Path, mirror: Path, label: str) -> bool:
    if not mirror.exists() or canonical.read_bytes() != mirror.read_bytes():
        print(f"stale {label}: {mirror}", file=sys.stderr)
        return True
    return False


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--spec", type=Path, default=SPEC)
    parser.add_argument("--c-ids-out", type=Path, default=PROTO_DIR / "vivid_display_protocol_ids.h")
    parser.add_argument(
        "--gnome-ids-out",
        type=Path,
        default=REPO_ROOT / "consumer/gnome/src/protocol/vivid_display_protocol_ids.h",
    )
    parser.add_argument("--gnome-out", type=Path, required=True)
    parser.add_argument("--gnome-codec-out", type=Path, required=True)
    parser.add_argument("--kde-out", type=Path, required=True)
    parser.add_argument("--kde-cpp-out", type=Path, required=True)
    parser.add_argument("--webui-out", type=Path, required=True)
    parser.add_argument("--webui-codec-out", type=Path, required=True)
    parser.add_argument("--gnome-meta-out", type=Path, required=True)
    parser.add_argument("--kde-meta-out", type=Path, required=True)
    parser.add_argument("--webui-meta-out", type=Path, required=True)
    parser.add_argument("--c-json-out", type=Path, required=True)
    parser.add_argument("--gnome-json-h-out", type=Path, required=True)
    parser.add_argument("--gnome-json-out", type=Path, required=True)
    parser.add_argument("--kde-json-out", type=Path, required=True)
    parser.add_argument("--webui-json-out", type=Path, required=True)
    parser.add_argument("--config-schema-out", type=Path, required=True)
    parser.add_argument("--webui-config-keys-out", type=Path, required=True)
    parser.add_argument(
        "--umbrella-canonical",
        type=Path,
        default=PROTO_DIR / "vivid_display_protocol.h",
    )
    parser.add_argument(
        "--umbrella-gnome",
        type=Path,
        default=REPO_ROOT / "consumer/gnome/src/protocol/vivid_display_protocol.h",
    )
    parser.add_argument(
        "--codec-canonical",
        type=Path,
        default=PROTO_DIR / "vivid_display_codec.c",
    )
    parser.add_argument(
        "--codec-gnome",
        type=Path,
        default=REPO_ROOT / "consumer/gnome/src/protocol/vivid_display_codec.c",
    )
    parser.add_argument(
        "--docs-reference-out",
        type=Path,
        default=REPO_ROOT / "docs/protocols-reference.md",
    )
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    spec = load_spec(args.spec)
    layouts = parse_message_layouts(spec)
    validate_spec(spec, layouts)
    defines = build_defines(spec, layouts)
    json_groups = parse_json_field_groups(spec)
    config_members = parse_config_key_members(spec)

    c_ids = emit_c_ids(spec, layouts)
    outputs = {
        args.c_ids_out: c_ids,
        args.gnome_ids_out: c_ids,
        args.gnome_out: emit_js(defines),
        args.gnome_codec_out: emit_js_codec(layouts, defines),
        args.kde_out: emit_hpp(defines),
        args.kde_cpp_out: emit_kde_cpp(spec, layouts),
        args.webui_out: emit_py(defines),
        args.webui_codec_out: emit_py_codec(layouts),
        args.gnome_meta_out: emit_js_meta(spec),
        args.kde_meta_out: emit_hpp_meta(spec),
        args.webui_meta_out: emit_py_meta(spec),
        args.c_json_out: emit_c_json_fields(json_groups),
        args.gnome_json_h_out: emit_c_json_fields(json_groups),
        args.gnome_json_out: emit_js_json_fields(json_groups),
        args.kde_json_out: emit_hpp_json_fields(json_groups),
        args.webui_json_out: emit_py_json_fields(json_groups),
        args.config_schema_out: emit_c_config_schema(config_members),
        args.webui_config_keys_out: emit_py_config_keys(config_members),
        args.docs_reference_out: emit_docs_reference(
            spec, layouts, json_groups, config_members
        ),
    }

    stale = False
    for path, content in outputs.items():
        if args.check:
            if not path.exists() or path.read_text(encoding="utf-8") != content:
                print(f"stale generated file: {path}", file=sys.stderr)
                stale = True
            continue
        if write_if_changed(path, content):
            print(f"updated {path}")

    if args.check:
        stale = check_bytes(args.umbrella_canonical, args.umbrella_gnome, "umbrella header") or stale
        stale = check_bytes(args.codec_canonical, args.codec_gnome, "codec.c") or stale
    else:
        if sync_bytes(args.umbrella_canonical, args.umbrella_gnome):
            print(f"updated {args.umbrella_gnome}")
        if sync_bytes(args.codec_canonical, args.codec_gnome):
            print(f"updated {args.codec_gnome}")

    if args.check and stale:
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
